var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();var player=UnityEngine.Object.FindAnyObjectByType<PlayerThrow>();var input=player.GetComponent<UnityEngine.InputSystem.PlayerInput>();
var report=new{scene=scene.path,scene.isDirty,Application.isPlaying,player=player.name,position=player.transform.position.ToString(),eye=player.Origin.position.ToString(),forward=player.transform.forward.ToString(),prefab=PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(player.gameObject),canvases=UnityEngine.Object.FindObjectsByType<Canvas>(FindObjectsSortMode.None).Length,fonts=AssetDatabase.FindAssets("t:TMP_FontAsset"),items=System.Linq.Enumerable.ToArray(System.Linq.Enumerable.Select(AssetDatabase.FindAssets("t:ItemDefinition"),AssetDatabase.GUIDToAssetPath)),events=System.Linq.Enumerable.ToArray(System.Linq.Enumerable.Select(input.actionEvents,x=>new{action=x.actionName,id=x.actionId,listeners=x.GetPersistentEventCount()})),actions=System.Linq.Enumerable.ToArray(System.Linq.Enumerable.Select(input.actions.FindActionMap("Player").actions,x=>new{name=x.name,bindings=System.Linq.Enumerable.ToArray(System.Linq.Enumerable.Select(x.bindings,b=>b.path))}))};

return Newtonsoft.Json.JsonConvert.SerializeObject(report);
